"use client";

import { mergeProps } from "@base-ui/react/merge-props";
import { useRender } from "@base-ui/react/use-render";
import { cva, type VariantProps } from "class-variance-authority";
import * as React from "react";

import { AsciiVRule } from "@/components/ascii/ascii-box";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Separator } from "@/components/ui/separator";
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from "@/components/ui/sheet";
import { Skeleton } from "@/components/ui/skeleton";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import { useIsMobile } from "@/hooks/use-mobile";
import { cn } from "@/lib/utils";

const SIDEBAR_COOKIE_NAME = "sidebar_state";
const SIDEBAR_COOKIE_MAX_AGE = 60 * 60 * 24 * 7;
const SIDEBAR_WIDTH = "25ch";
const SIDEBAR_WIDTH_MOBILE = "clamp(20ch, 60dvw, 28ch)";
const SIDEBAR_WIDTH_ICON = "4ch";
const SIDEBAR_KEYBOARD_SHORTCUT = "b";

type SidebarContextProps = {
  state: "expanded" | "collapsed";
  open: boolean;
  setOpen: (open: boolean) => void;
  openMobile: boolean;
  setOpenMobile: (open: boolean) => void;
  isMobile: boolean;
  toggleSidebar: () => void;
};

const SidebarContext = React.createContext<SidebarContextProps | null>(null);

function useSidebar() {
  const context = React.useContext(SidebarContext);
  if (!context) {
    throw new Error("useSidebar must be used within a SidebarProvider.");
  }

  return context;
}

function SidebarProvider({
  defaultOpen = true,
  open: openProp,
  onOpenChange: setOpenProp,
  className,
  style,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  defaultOpen?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
}) {
  const isMobile = useIsMobile();
  const [openMobile, setOpenMobile] = React.useState(false);

  // This is the internal state of the sidebar.
  // We use openProp and setOpenProp for control from outside the component.
  const [_open, _setOpen] = React.useState(defaultOpen);
  const open = openProp ?? _open;
  const setOpen = React.useCallback(
    (value: boolean | ((value: boolean) => boolean)) => {
      const openState = typeof value === "function" ? value(open) : value;
      if (setOpenProp) {
        setOpenProp(openState);
      } else {
        _setOpen(openState);
      }

      // This sets the cookie to keep the sidebar state.
      document.cookie = `${SIDEBAR_COOKIE_NAME}=${openState}; path=/; max-age=${SIDEBAR_COOKIE_MAX_AGE}`;
    },
    [setOpenProp, open]
  );

  // Helper to toggle the sidebar.
  const toggleSidebar = React.useCallback(() => {
    return isMobile ? setOpenMobile((open) => !open) : setOpen((open) => !open);
  }, [isMobile, setOpen, setOpenMobile]);

  // Adds a keyboard shortcut to toggle the sidebar.
  React.useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      if (
        event.key === SIDEBAR_KEYBOARD_SHORTCUT &&
        (event.metaKey || event.ctrlKey)
      ) {
        event.preventDefault();
        toggleSidebar();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [toggleSidebar]);

  // We add a state so that we can do data-state="expanded" or "collapsed".
  // This makes it easier to style the sidebar with Tailwind classes.
  const state = open ? "expanded" : "collapsed";

  const contextValue = React.useMemo<SidebarContextProps>(
    () => ({
      state,
      open,
      setOpen,
      isMobile,
      openMobile,
      setOpenMobile,
      toggleSidebar,
    }),
    [state, open, setOpen, isMobile, openMobile, setOpenMobile, toggleSidebar]
  );

  return (
    <SidebarContext.Provider value={contextValue}>
      <div
        data-slot="sidebar-wrapper"
        style={
          {
            "--sidebar-width": SIDEBAR_WIDTH,
            "--sidebar-width-icon": SIDEBAR_WIDTH_ICON,
            ...style,
          } as React.CSSProperties
        }
        className={cn(
          "group/sidebar-wrapper relative flex h-full w-full overflow-hidden has-data-[variant=inset]:bg-sidebar",
          className
        )}
        {...props}
      >
        {children}
      </div>
    </SidebarContext.Provider>
  );
}

function Sidebar({
  side = "left",
  variant = "sidebar",
  collapsible = "offcanvas",
  className,
  children,
  dir,
  ...props
}: React.ComponentProps<"div"> & {
  side?: "left" | "right";
  variant?: "sidebar" | "floating" | "inset";
  collapsible?: "offcanvas" | "icon" | "none";
}) {
  const { isMobile, state, openMobile, setOpenMobile } = useSidebar();

  if (collapsible === "none") {
    return (
      <div
        data-slot="sidebar"
        className={cn(
          "flex h-full w-(--sidebar-width) flex-col bg-sidebar text-sidebar-foreground",
          className
        )}
        {...props}
      >
        {children}
      </div>
    );
  }

  if (isMobile) {
    return (
      <Sheet open={openMobile} onOpenChange={setOpenMobile} {...props}>
        <SheetContent
          dir={dir}
          data-sidebar="sidebar"
          data-slot="sidebar"
          data-mobile="true"
          className="w-(--sidebar-width) bg-sidebar p-0 text-sidebar-foreground [&>button]:hidden"
          style={
            {
              "--sidebar-width": SIDEBAR_WIDTH_MOBILE,
            } as React.CSSProperties
          }
          side={side}
        >
          <SheetHeader className="sr-only">
            <SheetTitle>Sidebar</SheetTitle>
            <SheetDescription>Displays the mobile sidebar.</SheetDescription>
          </SheetHeader>
          <div className="flex h-full w-full flex-col">{children}</div>
        </SheetContent>
      </Sheet>
    );
  }

  return (
    <div
      className="group peer hidden text-sidebar-foreground md:block"
      data-state={state}
      data-collapsible={state === "collapsed" ? collapsible : ""}
      data-variant={variant}
      data-side={side}
      data-slot="sidebar"
    >
      {/* This is what handles the sidebar gap on desktop */}
      <div
        data-slot="sidebar-gap"
        className={cn(
          "relative w-(--sidebar-width) bg-transparent",
          "group-data-[collapsible=offcanvas]:w-0",
          "group-data-[side=right]:rotate-180",
          variant === "floating" || variant === "inset"
            ? "group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4)))]"
            : "group-data-[collapsible=icon]:w-(--sidebar-width-icon)"
        )}
      />
      <div
        data-slot="sidebar-container"
        data-side={side}
        className={cn(
          "absolute inset-y-0 z-10 hidden h-full w-(--sidebar-width) data-[side=left]:left-0 data-[side=left]:group-data-[collapsible=offcanvas]:left-[calc(var(--sidebar-width)*-1)] data-[side=right]:right-0 data-[side=right]:group-data-[collapsible=offcanvas]:right-[calc(var(--sidebar-width)*-1)] md:flex",
          // Adjust the padding for floating and inset variants.
          variant === "floating" || variant === "inset"
            ? "px-[2ch] py-[1lh] group-data-[collapsible=icon]:w-[calc(var(--sidebar-width-icon)+(--spacing(4))+2px)]"
            : "group-data-[collapsible=icon]:w-(--sidebar-width-icon)",
          className
        )}
        {...props}
      >
        <div
          data-sidebar="sidebar"
          data-slot="sidebar-inner"
          className="relative flex size-full flex-col bg-sidebar group-data-[variant=floating]:shadow-sm"
        >
          {children}
          {/* The sidebar's border: a column of "|" glyphs on its inner
           * edge, matching the frame color used across the components. */}
          <AsciiVRule
            side="right"
            className="pointer-events-none absolute inset-y-0 group-data-[side=left]:right-0 group-data-[side=right]:left-0"
          />
        </div>
      </div>
    </div>
  );
}

function SidebarTrigger({
  className,
  onClick,
  ...props
}: React.ComponentProps<typeof Button>) {
  const { toggleSidebar } = useSidebar();

  return (
    <Button
      data-sidebar="trigger"
      data-slot="sidebar-trigger"
      variant="ghost"
      size="icon"
      className={cn(className)}
      onClick={(event) => {
        onClick?.(event);
        toggleSidebar();
      }}
      {...props}
    >
      =<span className="sr-only">Toggle Sidebar</span>
    </Button>
  );
}

function SidebarRail({ className, ...props }: React.ComponentProps<"button">) {
  const { toggleSidebar } = useSidebar();

  return (
    <button
      data-sidebar="rail"
      data-slot="sidebar-rail"
      aria-label="Toggle Sidebar"
      tabIndex={-1}
      onClick={toggleSidebar}
      title="Toggle Sidebar"
      className={cn(
        "absolute inset-y-0 z-20 hidden w-4 group-data-[side=left]:-right-4 group-data-[side=right]:left-0 sm:flex ltr:-translate-x-1/2 rtl:-translate-x-1/2",
        "in-data-[side=left]:cursor-w-resize in-data-[side=right]:cursor-e-resize",
        "[[data-side=left][data-state=collapsed]_&]:cursor-e-resize [[data-side=right][data-state=collapsed]_&]:cursor-w-resize",
        "group-data-[collapsible=offcanvas]:translate-x-0 group-data-[collapsible=offcanvas]:after:left-full hover:group-data-[collapsible=offcanvas]:bg-sidebar",
        "[[data-side=left][data-collapsible=offcanvas]_&]:-right-2",
        "[[data-side=right][data-collapsible=offcanvas]_&]:-left-2",
        className
      )}
      {...props}
    />
  );
}

function SidebarInset({ className, ...props }: React.ComponentProps<"main">) {
  return (
    <main
      data-slot="sidebar-inset"
      className={cn(
        "relative flex min-w-0 flex-1 flex-col bg-background md:peer-data-[variant=inset]:m-2 md:peer-data-[variant=inset]:ml-0 md:peer-data-[variant=inset]:rounded-xl md:peer-data-[variant=inset]:shadow-sm md:peer-data-[variant=inset]:peer-data-[state=collapsed]:ml-2",
        className
      )}
      {...props}
    />
  );
}

function SidebarInput({
  className,
  ...props
}: React.ComponentProps<typeof Input>) {
  return (
    <Input
      data-slot="sidebar-input"
      data-sidebar="input"
      className={cn("h-8 w-full bg-background shadow-none", className)}
      {...props}
    />
  );
}

function SidebarHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-header"
      data-sidebar="header"
      className={cn("flex flex-col px-[2ch] py-[1lh]", className)}
      {...props}
    />
  );
}

function SidebarFooter({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-footer"
      data-sidebar="footer"
      className={cn("flex flex-col px-[2ch] py-[1lh]", className)}
      {...props}
    />
  );
}

function SidebarSeparator({
  className,
  ...props
}: React.ComponentProps<typeof Separator>) {
  return (
    <Separator
      data-slot="sidebar-separator"
      data-sidebar="separator"
      className={cn("mx-[2ch] w-auto", className)}
      {...props}
    />
  );
}

function SidebarContent({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-content"
      data-sidebar="content"
      className={cn(
        "no-scrollbar flex min-h-0 flex-1 flex-col gap-0 overflow-auto outline-none group-data-[collapsible=icon]:overflow-hidden",
        className
      )}
      {...props}
    />
  );
}

function SidebarGroup({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-group"
      data-sidebar="group"
      className={cn(
        "relative flex w-full min-w-0 flex-col px-[1ch] pt-[1lh]",
        className
      )}
      {...props}
    />
  );
}

function SidebarGroupLabel({
  className,
  render,
  ...props
}: useRender.ComponentProps<"div"> & React.ComponentProps<"div">) {
  return useRender({
    defaultTagName: "div",
    props: mergeProps<"div">(
      {
        className: cn(
          "flex h-8 shrink-0 items-center rounded-md px-[2ch] text-sm text-sidebar-foreground/70 outline-hidden group-data-[collapsible=icon]:-mt-8 group-data-[collapsible=icon]:opacity-0 focus-visible:text-sidebar-foreground [&>svg]:size-4 [&>svg]:shrink-0",
          className
        ),
      },
      props
    ),
    render,
    state: {
      slot: "sidebar-group-label",
      sidebar: "group-label",
    },
  });
}

function SidebarGroupAction({
  className,
  render,
  ...props
}: useRender.ComponentProps<"button"> & React.ComponentProps<"button">) {
  return useRender({
    defaultTagName: "button",
    props: mergeProps<"button">(
      {
        className: cn(
          "absolute top-3.5 right-3 flex aspect-square w-5 items-center justify-center rounded-md p-0 text-sidebar-foreground outline-hidden group-data-[collapsible=icon]:hidden after:absolute after:-inset-2 hover:text-sidebar-accent-foreground focus-visible:text-sidebar-accent-foreground md:after:hidden [&>svg]:size-4 [&>svg]:shrink-0",
          className
        ),
      },
      props
    ),
    render,
    state: {
      slot: "sidebar-group-action",
      sidebar: "group-action",
    },
  });
}

function SidebarGroupContent({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-group-content"
      data-sidebar="group-content"
      className={cn("w-full text-sm", className)}
      {...props}
    />
  );
}

function SidebarMenu({ className, ...props }: React.ComponentProps<"ul">) {
  return (
    <ul
      data-slot="sidebar-menu"
      data-sidebar="menu"
      className={cn("flex w-full min-w-0 flex-col gap-0", className)}
      {...props}
    />
  );
}

function SidebarMenuItem({ className, ...props }: React.ComponentProps<"li">) {
  return (
    <li
      data-slot="sidebar-menu-item"
      data-sidebar="menu-item"
      className={cn("group/menu-item relative", className)}
      {...props}
    />
  );
}

const sidebarMenuButtonVariants = cva(
  "peer/menu-button group/menu-button flex w-full items-center gap-[1ch] overflow-hidden rounded-md px-[2ch] py-[1lh] text-left text-sm outline-hidden group-has-data-[sidebar=menu-action]/menu-item:pr-[2ch] group-data-[collapsible=icon]:size-8! group-data-[collapsible=icon]:p-[2ch]! hover:text-sidebar-accent-foreground focus-visible:text-sidebar-accent-foreground active:text-sidebar-accent-foreground disabled:pointer-events-none disabled:opacity-50 aria-disabled:pointer-events-none aria-disabled:opacity-50 data-open:hover:text-sidebar-accent-foreground data-active:data-active:text-sidebar-accent-foreground [&_svg]:size-4 [&_svg]:shrink-0 [&>span:last-child]:truncate",
  {
    variants: {
      variant: {
        default: "hover:text-sidebar-accent-foreground",
        outline: "bg-background hover:text-sidebar-accent-foreground",
      },
      size: {
        default: "h-8 text-sm",
        sm: "h-7 text-sm",
        lg: "h-12 text-sm group-data-[collapsible=icon]:p-0!",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  }
);

function SidebarMenuButton({
  render,
  isActive = false,
  variant = "default",
  size = "default",
  tooltip,
  className,
  ...props
}: useRender.ComponentProps<"button"> &
  React.ComponentProps<"button"> & {
    isActive?: boolean;
    tooltip?: string | React.ComponentProps<typeof TooltipContent>;
  } & VariantProps<typeof sidebarMenuButtonVariants>) {
  const { isMobile, state } = useSidebar();
  const comp = useRender({
    defaultTagName: "button",
    props: mergeProps<"button">(
      {
        className: cn(sidebarMenuButtonVariants({ variant, size }), className),
      },
      props
    ),
    render: !tooltip ? render : <TooltipTrigger render={render} />,
    state: {
      slot: "sidebar-menu-button",
      sidebar: "menu-button",
      size,
      active: isActive,
    },
  });

  if (!tooltip) {
    return comp;
  }

  if (typeof tooltip === "string") {
    tooltip = {
      children: tooltip,
    };
  }

  return (
    <Tooltip>
      {comp}
      <TooltipContent
        side="right"
        align="center"
        hidden={state !== "collapsed" || isMobile}
        {...tooltip}
      />
    </Tooltip>
  );
}

function SidebarMenuAction({
  className,
  render,
  showOnHover = false,
  ...props
}: useRender.ComponentProps<"button"> &
  React.ComponentProps<"button"> & {
    showOnHover?: boolean;
  }) {
  return useRender({
    defaultTagName: "button",
    props: mergeProps<"button">(
      {
        className: cn(
          "absolute top-1.5 right-1 flex aspect-square w-5 items-center justify-center rounded-md p-0 text-sidebar-foreground outline-hidden group-data-[collapsible=icon]:hidden peer-hover/menu-button:text-sidebar-accent-foreground peer-data-[size=default]/menu-button:top-1.5 peer-data-[size=lg]/menu-button:top-2.5 peer-data-[size=sm]/menu-button:top-1 after:absolute after:-inset-2 hover:text-sidebar-accent-foreground focus-visible:text-sidebar-accent-foreground md:after:hidden [&>svg]:size-4 [&>svg]:shrink-0",
          showOnHover &&
            "group-focus-within/menu-item:opacity-100 group-hover/menu-item:opacity-100 peer-data-active/menu-button:text-sidebar-accent-foreground aria-expanded:opacity-100 md:opacity-0",
          className
        ),
      },
      props
    ),
    render,
    state: {
      slot: "sidebar-menu-action",
      sidebar: "menu-action",
    },
  });
}

function SidebarMenuBadge({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="sidebar-menu-badge"
      data-sidebar="menu-badge"
      className={cn(
        "pointer-events-none absolute right-1 flex h-5 min-w-5 items-center justify-center rounded-md px-[2ch] text-sm text-sidebar-foreground tabular-nums select-none group-data-[collapsible=icon]:hidden peer-hover/menu-button:text-sidebar-accent-foreground peer-data-[size=default]/menu-button:top-1.5 peer-data-[size=lg]/menu-button:top-2.5 peer-data-[size=sm]/menu-button:top-1 peer-data-active/menu-button:text-sidebar-accent-foreground",
        className
      )}
      {...props}
    />
  );
}

function SidebarMenuSkeleton({
  className,
  showIcon = false,
  ...props
}: React.ComponentProps<"div"> & {
  showIcon?: boolean;
}) {
  // Random width between 50 to 90%.
  const [width] = React.useState(() => {
    return `${Math.floor(Math.random() * 40) + 50}%`;
  });

  return (
    <div
      data-slot="sidebar-menu-skeleton"
      data-sidebar="menu-skeleton"
      className={cn(
        "flex h-8 items-center gap-[1ch] rounded-md px-[2ch]",
        className
      )}
      {...props}
    >
      {showIcon && (
        <Skeleton
          className="size-4 rounded-md"
          data-sidebar="menu-skeleton-icon"
        />
      )}
      <Skeleton
        className="h-4 max-w-(--skeleton-width) flex-1"
        data-sidebar="menu-skeleton-text"
        style={
          {
            "--skeleton-width": width,
          } as React.CSSProperties
        }
      />
    </div>
  );
}

function SidebarMenuSub({ className, ...props }: React.ComponentProps<"ul">) {
  return (
    <div className="relative mx-3.5 translate-x-px group-data-[collapsible=icon]:hidden">
      <AsciiVRule side="left" className="absolute inset-y-0 left-0" />
      <ul
        data-slot="sidebar-menu-sub"
        data-sidebar="menu-sub"
        className={cn(
          "flex min-w-0 flex-col py-[1lh] pr-[2ch] pl-[2ch]",
          className
        )}
        {...props}
      />
    </div>
  );
}

function SidebarMenuSubItem({
  className,
  ...props
}: React.ComponentProps<"li">) {
  return (
    <li
      data-slot="sidebar-menu-sub-item"
      data-sidebar="menu-sub-item"
      className={cn("group/menu-sub-item relative", className)}
      {...props}
    />
  );
}

function SidebarMenuSubButton({
  render,
  size = "md",
  isActive = false,
  className,
  ...props
}: useRender.ComponentProps<"a"> &
  React.ComponentProps<"a"> & {
    size?: "sm" | "md";
    isActive?: boolean;
  }) {
  return useRender({
    defaultTagName: "a",
    props: mergeProps<"a">(
      {
        className: cn(
          "flex h-7 min-w-0 -translate-x-px items-center gap-[1ch] overflow-hidden rounded-md px-[2ch] text-sidebar-foreground outline-hidden group-data-[collapsible=icon]:hidden hover:text-sidebar-accent-foreground focus-visible:text-sidebar-accent-foreground active:text-sidebar-accent-foreground disabled:pointer-events-none disabled:opacity-50 aria-disabled:pointer-events-none aria-disabled:opacity-50 text-sm data-active:bg-sidebar-accent data-active:text-sidebar-accent-foreground [&>span:last-child]:truncate [&>svg]:size-4 [&>svg]:shrink-0 [&>svg]:text-sidebar-accent-foreground",
          className
        ),
      },
      props
    ),
    render,
    state: {
      slot: "sidebar-menu-sub-button",
      sidebar: "menu-sub-button",
      size,
      active: isActive,
    },
  });
}

export {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupAction,
  SidebarGroupContent,
  SidebarGroupLabel,
  SidebarHeader,
  SidebarInput,
  SidebarInset,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuBadge,
  SidebarMenuButton,
  SidebarMenuItem,
  SidebarMenuSkeleton,
  SidebarMenuSub,
  SidebarMenuSubButton,
  SidebarMenuSubItem,
  SidebarProvider,
  SidebarRail,
  SidebarSeparator,
  SidebarTrigger,
  useSidebar,
};

"use client";

import * as React from "react";

import { useAsciiChars } from "@/components/ascii/ascii-chars";
import {
  type AsciiChars,
  bottomBorder,
  dividerBorder,
  fill,
  junctionGlyph,
  topBorder,
  vColumn,
  vGlyph,
} from "@/lib/ascii";
import { cn } from "@/lib/utils";

type Tone = "primary" | "soft";

/** Which line of the glyph set a rule draws with. */
type AsciiLine = keyof Omit<AsciiChars, "junction">;

/* Every ASCII frame in the app shares one border color (matching the
 * inputs' and menus' rest-state frames). The tone axis is kept as API
 * so emphasis can be reintroduced without touching call sites. */
const toneClass: Record<Tone, string> = {
  primary: "text-primary/60",
  soft: "text-primary/60",
};

const AsciiBoxContext = React.createContext<{
  width: number;
  tone: Tone;
  /** Background utility class of the box surface — dividers repaint it
   * over the absolute side rules so intersections show only junctions. */
  bg: string;
  /** Fluid boxes take their width from CSS, so dividers are drawn as
   * clipped rules instead of fixed-length strings. */
  fluid: boolean;
}>({
  width: 40,
  tone: "soft",
  bg: "bg-card",
  fluid: false,
});

/** The junction glyph ("+" by default) — for corners and intersections
 * drawn outside a full AsciiBox (layout frames, fluid borders). */
function AsciiJunction({
  className,
  ...props
}: Omit<React.ComponentProps<"span">, "children">) {
  const chars = useAsciiChars();
  return (
    <span aria-hidden className={cn("select-none", className)} {...props}>
      {junctionGlyph(chars)}
    </span>
  );
}

/** One glyph of a vertical edge — for single-row frames (inputs,
 * menu items, table rows) that draw their own sides per row. */
function AsciiSide({
  side = "left",
  row = 0,
  className,
  ...props
}: Omit<React.ComponentProps<"span">, "children"> & {
  side?: "left" | "right";
  row?: number;
}) {
  const chars = useAsciiChars();
  return (
    <span aria-hidden className={cn("select-none", className)} {...props}>
      {vGlyph(chars[side], row)}
    </span>
  );
}

/** A fixed-width "+----+" edge row for frames sized in characters —
 * the top (optionally titled) or bottom border of an input, menu,
 * avatar… Rendered as a block span so it can sit inside buttons. */
function AsciiEdge({
  edge,
  width,
  title,
  className,
  ...props
}: Omit<React.ComponentProps<"span">, "children" | "title"> & {
  edge: "top" | "bottom";
  width: number;
  title?: string;
}) {
  const chars = useAsciiChars();
  return (
    <span
      aria-hidden
      className={cn("block select-none whitespace-pre", className)}
      {...props}
    >
      {edge === "top"
        ? topBorder(width, title, chars)
        : bottomBorder(width, chars)}
    </span>
  );
}

/** A column of side glyphs that stretches to match its sibling's
 * height via flex `items-stretch` — real glyphs, clipped by overflow. */
function AsciiVRule({
  tone = "soft",
  side = "left",
  className,
}: {
  tone?: Tone;
  side?: "left" | "right";
  className?: string;
}) {
  const chars = useAsciiChars();
  return (
    <div
      aria-hidden
      className={cn(
        "w-[1ch] shrink-0 select-none overflow-hidden",
        toneClass[tone],
        className
      )}
    >
      <pre className="m-0 font-mono">{vColumn(300, chars[side])}</pre>
    </div>
  );
}

/** One or more literal empty text rows — vertical padding that stays
 * on the character grid instead of arbitrary CSS lengths. */
function AsciiPad({
  rows = 1,
  className,
}: {
  rows?: number;
  className?: string;
}) {
  return (
    <div aria-hidden className={cn("select-none whitespace-pre", className)}>
      {Array.from({ length: rows }, () => " ").join("\n")}
    </div>
  );
}

type AsciiBoxProps = Omit<React.ComponentProps<"div">, "title"> & {
  width: number;
  title?: string;
  tone?: Tone;
  contentClassName?: string;
  /** Empty text rows rendered above and below the content. */
  padY?: number;
  /** Background utility class of the box surface. Pass this instead of a
   * bg-* class in className so dividers can repaint it at intersections. */
  bg?: string;
  /** Size the box with CSS (w-*, max-w-*) instead of `width`: the edge
   * rows become clipped rules that follow the container, so the box can
   * be `w-full` on a narrow screen. `width` is then only the fallback
   * used when no width class is given. */
  fluid?: boolean;
};

function AsciiBox({
  width,
  title,
  tone = "soft",
  bg = "bg-card",
  className,
  contentClassName,
  padY = 0,
  fluid = false,
  children,
  ...props
}: AsciiBoxProps) {
  const chars = useAsciiChars();
  return (
    <AsciiBoxContext.Provider value={{ width, tone, bg, fluid }}>
      <div
        data-slot="ascii-box"
        className={cn(
          "inline-flex flex-col font-mono text-card-foreground text-sm",
          bg,
          className
        )}
        style={fluid ? undefined : { width: `${width}ch` }}
        {...props}
      >
        {fluid ? (
          <div
            aria-hidden
            className={cn("flex select-none whitespace-pre", toneClass[tone])}
          >
            <AsciiJunction className="shrink-0" />
            {title ? (
              <>
                <AsciiRule
                  line="top"
                  tone={tone}
                  className="w-[2ch] shrink-0 text-inherit"
                />
                <span className="shrink-0">{` ${title} `}</span>
              </>
            ) : null}
            <AsciiRule
              line="top"
              tone={tone}
              className="min-w-0 flex-1 text-inherit"
            />
            <AsciiJunction className="shrink-0" />
          </div>
        ) : (
          <div
            aria-hidden
            className={cn("select-none whitespace-pre", toneClass[tone])}
          >
            {topBorder(width, title, chars)}
          </div>
        )}
        <div className="relative">
          <AsciiVRule
            tone={tone}
            side="left"
            className="absolute inset-y-0 left-0"
          />
          {padY > 0 && <AsciiPad rows={padY} />}
          <div className={cn("min-w-0 px-[2ch]", contentClassName)}>
            {children}
          </div>
          {padY > 0 && <AsciiPad rows={padY} />}
          <AsciiVRule
            tone={tone}
            side="right"
            className="absolute inset-y-0 right-0"
          />
        </div>
        {fluid ? (
          <AsciiHBorder line="bottom" tone={tone} />
        ) : (
          <div
            aria-hidden
            className={cn("select-none whitespace-pre", toneClass[tone])}
          >
            {bottomBorder(width, chars)}
          </div>
        )}
      </div>
    </AsciiBoxContext.Provider>
  );
}

/** A "+---+" divider spanning the box's full content width, flanked
 * by one empty text row on each side (disable with pad={false}) —
 * for separating sections (header/content/footer) inside an AsciiBox. */
function AsciiBoxDivider({
  className,
  pad = true,
}: {
  className?: string;
  pad?: boolean;
}) {
  const { width, tone, bg, fluid } = React.useContext(AsciiBoxContext);
  const chars = useAsciiChars();
  return (
    <div
      aria-hidden
      className={cn(
        "-mx-[2ch] select-none whitespace-pre",
        toneClass[tone],
        className
      )}
    >
      {pad && <div> </div>}
      {/* Positioned above the box's absolute side rules and repainting
       * the surface, so the intersection cells show only junctions. */}
      <div className={cn("relative z-10", bg)}>
        {fluid ? (
          <AsciiHBorder line="divider" tone={tone} />
        ) : (
          <span>{dividerBorder(width, chars)}</span>
        )}
      </div>
      {pad && <div> </div>}
    </div>
  );
}

/** A single side-glyph-flanked line — for list-style rows (menus, table
 * rows) that need their own hover/selection background per row. */
function AsciiBoxRow({
  className,
  contentClassName,
  children,
  ...props
}: React.ComponentProps<"div"> & { contentClassName?: string }) {
  const { tone } = React.useContext(AsciiBoxContext);
  return (
    <div className={cn("-mx-[2ch] flex items-center", className)} {...props}>
      <AsciiSide side="left" className={cn("shrink-0", toneClass[tone])} />
      <div className={cn("min-w-0 flex-1 px-[1ch]", contentClassName)}>
        {children}
      </div>
      <AsciiSide side="right" className={cn("shrink-0", toneClass[tone])} />
    </div>
  );
}

/** A fluid single-character-tall rule for contexts where the exact
 * character width isn't known ahead of time (e.g. spans a flexible
 * container). Renders real repeated glyphs, clipped by overflow.
 *
 * Draws with the theme's `divider` line (horizontal) or `left` line
 * (vertical) unless `line` picks another edge; `char` overrides the
 * theme entirely. */
function AsciiRule({
  className,
  char,
  line,
  tone = "soft",
  orientation = "horizontal",
}: {
  className?: string;
  char?: string;
  line?: AsciiLine;
  tone?: Tone;
  orientation?: "horizontal" | "vertical";
}) {
  const chars = useAsciiChars();
  const vertical = orientation === "vertical";
  const seq = char ?? chars[line ?? (vertical ? "left" : "divider")];
  return (
    <div
      aria-hidden
      className={cn(
        "select-none overflow-hidden whitespace-pre text-nowrap",
        toneClass[tone],
        className
      )}
    >
      {vertical ? vColumn(300, seq) : fill(400, seq)}
    </div>
  );
}

/** A fluid "+----+" row: junction, a horizontal line that fills the
 * available width, junction. For box edges whose width is set by
 * layout rather than a character count. */
function AsciiHBorder({
  line = "top",
  tone = "soft",
  className,
  ...props
}: Omit<React.ComponentProps<"div">, "children"> & {
  line?: AsciiLine;
  tone?: Tone;
}) {
  return (
    <div
      aria-hidden
      className={cn("flex select-none", toneClass[tone], className)}
      {...props}
    >
      <AsciiJunction className="shrink-0" />
      <AsciiRule line={line} tone={tone} className="min-w-0 flex-1" />
      <AsciiJunction className="shrink-0" />
    </div>
  );
}

